
import { Box, Button, Flex, Icon, IconButton } from "@chakra-ui/react";
import zillionparts_logo from '../../assets/zillion_parts_logo_7.webp'
import { useDispatch, useSelector } from "react-redux";
import { resetAppliedFilters, setCategoryPath, setCurrentPage, setFiltersErrorMessage, setFiltersloading, setFiltersObject, setFullProductsList, setInitialFilters, setKeyWordSearchErrorMessage, setKeyWordSearchIsLoading, setKeywordSearchValue, setNameToHighlight, setProductsList, setSearchList, setSelectedCategory, setSelectedCategoryNotFound, setSelectedFilters, setShowCategoryAdd, setShowCategoryUpload, setShowDeleteCategory, setTotalItems } from "../../state/searchState/searchSlice";

export default function Header() {
    const showCategoryUpload = useSelector((state)=> state.search.showCategoryUpload)
    const showCategoryAdd = useSelector((state)=> state.search.showCategoryAdd)
    const showDeleteCategory = useSelector((state)=> state.search.showDeleteCategory)
    const filtersLoading = useSelector((state)=> state.search.filtersLoading)
  const dispatch = useDispatch()
    const prods = useSelector((state)=>state.search.productsList)
  function homeOnClick(){
    dispatch(setFiltersObject(null))
    dispatch(setProductsList([]))
    dispatch(setSelectedCategory(null))
    dispatch(setNameToHighlight(""))
    dispatch(setCategoryPath(""))
    dispatch(setFullProductsList([]))
    dispatch(setInitialFilters(null))
    dispatch(setCurrentPage(1))
    dispatch(setKeywordSearchValue(""))
    dispatch(setKeyWordSearchIsLoading(false))
    dispatch(setKeyWordSearchErrorMessage(""))
    dispatch(setSearchList(null))
    dispatch(setFiltersloading(false))
    dispatch(setSelectedCategoryNotFound(false))
    dispatch(setFiltersErrorMessage(""))
    dispatch(setSelectedFilters({}))
    dispatch(setTotalItems(0))
    dispatch(resetAppliedFilters({}))
  }
  function AddCategoryClick(){
    homeOnClick()
    dispatch(setShowCategoryAdd(true))
  }

  function DeleteCategoryOnclick(){
    dispatch(setShowDeleteCategory(true))
  }
  // Simple arrow icon component
  const ArrowBackIcon = (props) => (
    <Icon viewBox="0 0 24 24" {...props}>
      <svg>
      <path
        fill="white"
        d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z"
      />
      </svg>
    </Icon>
  );
  
  return (
    <Box bg="white" px={6} py={4} color="white">
      <Flex align="center" justify="space-between">
        <img src={zillionparts_logo} width="100px" height="70px" alt="Zillion Parts Logo"/>
        {
          prods.length > 0? <IconButton
          disabled = {filtersLoading}
          onClick={homeOnClick}

          size="md"
        >
          <ArrowBackIcon/>
        </IconButton>: <></>
        }
        {
          showCategoryAdd == false && showDeleteCategory == false && prods.length == 0? <Button
          disabled ={filtersLoading}
          _hover={{ bg: "#0D3D54" }}
          bg="#0E5870"

          onClick={AddCategoryClick}
          >
            Add Category
          </Button>: <></>
        }
        {
          showDeleteCategory == false && showCategoryAdd == false && prods.length == 0? <Button
          disabled ={filtersLoading}
          _hover={{ bg: "#0D3D54" }}
          bg="#0E5870"

          onClick={DeleteCategoryOnclick}
          >
            Delete Category
          </Button>: <></>
        }
        
      </Flex>
    </Box>
  );
}