import { Stack } from '@chakra-ui/react'
import React, { useEffect } from 'react'
import { useSelector } from 'react-redux'
import ProductItem from './ProductItem'
import PaginationComponent from './PaginationComponent'

function ProductsList() {
  const prods = useSelector((state)=>state.search.productsList)
  const currentPage = useSelector((state)=>state.search.currentPage)

  const startIndex = (currentPage - 1) * 10;
  const paginatedProducts =  prods.slice(startIndex, startIndex + 10);
  useEffect(()=>{
    console.log("prods is ")
   console.log(prods)
  }, [prods])
  return (
 <Stack marginRight="5%"  marginLeft="2%" flex="4" h="fit-content" >
  {
   paginatedProducts.map((prod, index)=>{
    const [key, value] = Object.entries(prod)[0];
    
    return <ProductItem key = {key} sku = {key} prodName = {value[0]} prodLink = {value[1]}/>
   })
  }
    <PaginationComponent/>

 </Stack>
  )
}

export default ProductsList
