import { Box, ProgressCircle, Stack, HStack} from '@chakra-ui/react'
import React from 'react'
import SearchBar from './SearchBar'
import { useSelector } from 'react-redux'
import AlertMessageComponent from './AlertMessageComponent'
import SearchResultsList from './SearchResultsList'

function SearchPage() {
const searchList = useSelector((state)=>state.search.searchList)
const isloading = useSelector((state)=>state.search.keyWordSearchIsLoading)
const errorMessage = useSelector((state)=>state.search.keyWordSearchErrorMessage)
const categoryNotFound = useSelector((state)=>state.search.selectedCategoryNotFound)
const filtersLoading = useSelector((state)=>state.search.filtersLoading)
  return (
<Stack  w="100%" h="100%" alignItems="flex-end" >
<SearchBar/>
{
    searchList == null? <></>: isloading == true? <HStack  width="100%" justifyContent="center"><ProgressCircle.Root  zIndex = '10' value={null} size = "md" marginBottom = '10px'>
          <ProgressCircle.Circle>
            <ProgressCircle.Track />
            <ProgressCircle.Range stroke='#0E5870' />
          </ProgressCircle.Circle>
        </ProgressCircle.Root></HStack>: errorMessage != ""? <AlertMessageComponent errorMessage = {errorMessage}/>: <SearchResultsList/>
}
{
  filtersLoading == true? <HStack  width="100%" justifyContent="center"><ProgressCircle.Root  zIndex = '10' value={null} size = "md" marginBottom = '10px'>
          <ProgressCircle.Circle>
            <ProgressCircle.Track />
            <ProgressCircle.Range stroke='#0E5870' />
          </ProgressCircle.Circle>
        </ProgressCircle.Root></HStack>: <></>
}
{
  categoryNotFound == true?  <AlertMessageComponent errorMessage = "category not processed yet"/>: <></>


}

</Stack>
  )
}

export default SearchPage
