import React from 'react'
import { ButtonGroup, IconButton, Pagination, Text, Flex } from "@chakra-ui/react"
import { LuChevronLeft, LuChevronRight } from "react-icons/lu"
import { useDispatch, useSelector } from 'react-redux'
import { setCurrentPage } from '../../state/searchState/searchSlice'

function PaginationComponent() {
  const dispatch = useDispatch()
  const totalItems = useSelector((state) => state.search.totalItems)
  const currentPage = useSelector((state) => state.search.currentPage)
  
  function onPageChange(value){
    console.log(value)
    dispatch(setCurrentPage(value))    
  }
  
  // Calculate the range of items shown on current page
  const startItem = (currentPage - 1) * 10 + 1
  const endItem = Math.min(currentPage * 10, totalItems)
  
  return (
    <Flex gap={4} alignItems="center">
      <Pagination.Root
        page={currentPage}
        onPageChange={(details) => onPageChange(details.page)}
        count={totalItems} 
        pageSize={10} 
        defaultPage={1}>
        <ButtonGroup variant="outline" size="sm">
          <Pagination.PrevTrigger asChild>
            <IconButton>
              <LuChevronLeft />
            </IconButton>
          </Pagination.PrevTrigger>
          <Pagination.Items
            render={(page) => (
              <IconButton 
                onClick={() => onPageChange(page.value)} 
                variant={{ base: "outline", _selected: "solid" }}>
                {page.value}
              </IconButton>
            )}
          />
          <Pagination.NextTrigger asChild>
            <IconButton>
              <LuChevronRight />
            </IconButton>
          </Pagination.NextTrigger>
        </ButtonGroup>
      </Pagination.Root>
      
      <Text fontSize="sm" color="gray.600">
        Showing {startItem}-{endItem} of {totalItems}
      </Text>
    </Flex>
  )
}

export default PaginationComponent