import { Stack, Box, Progress, ProgressCircle,  HStack, Select, Button, createListCollection, Portal } from '@chakra-ui/react'
import React, { useEffect, useMemo } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { setAllCategories, setAllCategoriesLoading, setCategoryToDelete, setDeleteCategoryLoading, setShowDeleteCategory } from '../../state/searchState/searchSlice'
import toast from 'react-hot-toast'
import api from '../../api';

function DeleteCategory() {
  const allCategories = useSelector((state) => state.search.allCategories)
  const allCategoriesLoading = useSelector((state) => state.search.allCategoriesLoading)
  const allCategoriesErrorMessage = useSelector((state) => state.search.allCategoriesErrorMessage)
  const deleteCategoryLoading = useSelector((state) => state.search.deleteCategoryLoading)
  const categoryToDelete = useSelector((state) => state.search.categoryToDelete)
  
  const dispatch = useDispatch()

  const categoryCollection = useMemo(() => {
    const itemsList = allCategories.map(val => ({
      label: val,
      value: val
    }))
    console.log(itemsList)
    return createListCollection({ items: itemsList })
  }, [allCategories])

  const handleValueChange = (details) => {
    dispatch(setCategoryToDelete(details.value[0]))
    console.log(details.value)
  }

  const onClickCancel = () => {
    dispatch(setShowDeleteCategory(false))
    dispatch(setCategoryToDelete(null))
  }

  const onClickDelete = async () => {
   try{
    dispatch(setDeleteCategoryLoading(true))
    var response = await api.post("/delete_category",{
        "category_id": categoryToDelete
    })
    if(response.data["detail"] == "fail"){
        throw Error(response.data["message"])
    }
   dispatch(setDeleteCategoryLoading(false))
   toast.success("Category successfully deleted.")
   dispatch(setShowDeleteCategory(false))
   dispatch(setCategoryToDelete(null))
   }catch(e){
    dispatch(setDeleteCategoryLoading(false))
    toast.error(String(e))

   }
  }

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        dispatch(setAllCategoriesLoading(true))
        const response = await api.post("/get_all_categories")
        if (response.data["detail"] === "fail") {
          throw new Error(response.data["message"])
        }
        dispatch(setAllCategoriesLoading(false))
        dispatch(setAllCategories(response.data["all_categories"]))
      } catch (e) {
        dispatch(setAllCategoriesLoading(false))
        dispatch(setShowDeleteCategory(false))
        toast.error(String(e))
      }
    }
    
    fetchCategories()
  }, [dispatch])
    
  return (
    <Stack w="100%" alignItems= "center" h="100%">
      {allCategoriesLoading === true ? (
        <Stack w= "100%" gap={50} alignItems= "center">
          <h2 style={{ color: "black", fontWeight: "bolder" }}>Fetching Categories</h2>
          {/* <Progress.Root maxW="340px" value={null}>
            <Progress.Track>
              <Progress.Range />
            </Progress.Track>
          </Progress.Root> */}

          <ProgressCircle.Root value={null} size="sm">
                               <ProgressCircle.Circle colorPalette="black">
                                 <ProgressCircle.Track />
                                 <ProgressCircle.Range />
                               </ProgressCircle.Circle>
                             </ProgressCircle.Root>
        </Stack>
      ) : deleteCategoryLoading == true?
      <Stack w= "100%" gap={50} alignItems= "center">
          <h2 style={{ color: "black", fontWeight: "bolder" }}>Deleting Category</h2>
          {/* <Progress.Root maxW="340px" value={null}>
            <Progress.Track>
              <Progress.Range />
            </Progress.Track>
          </Progress.Root> */}

          <ProgressCircle.Root value={null} size="sm">
                               <ProgressCircle.Circle colorPalette="black">
                                 <ProgressCircle.Track />
                                 <ProgressCircle.Range />
                               </ProgressCircle.Circle>
                             </ProgressCircle.Root>
        </Stack> :(
        <HStack justifyContent="space-evenly">
          <Select.Root
            value={categoryToDelete != null ? [categoryToDelete] : []}
            onValueChange={handleValueChange}
            disabled={deleteCategoryLoading}
            collection={categoryCollection}
            size="sm"
            width="320px"
          >
            <Select.HiddenSelect />
            <Select.Label>Category</Select.Label>
            <Select.Control>
              <Select.Trigger>
                <Select.ValueText placeholder="Category" />
              </Select.Trigger>
              <Select.IndicatorGroup>
                <Select.ClearTrigger />
                <Select.Indicator />
              </Select.IndicatorGroup>
            </Select.Control>
            <Portal>
              <Select.Positioner>
                <Select.Content>
                  {categoryCollection.items.map((val) => (
                    <Select.Item item={val} key={val.value}>
                      {val.label}
                      <Select.ItemIndicator />
                    </Select.Item>
                  ))}
                </Select.Content>
              </Select.Positioner>
            </Portal>
          </Select.Root>
          <Box
              w="20px"
              >
          
              </Box>
          <Stack w= "150px">
          <Button
            onClick={onClickCancel}
            _hover={{ bg: "gray" }}
            fontSize={{ sm: "14px", md: "16px", lg: "18px" }}
            w={{ sm: "70%", md: "80%", lg: "90%" }}
            minH="30px"
            minW="50px"
            px={4}
            color="white"
            bg="black"
            border="1px solid black"
            borderRadius="12px"
            h="100%"
            marginTop="10px"
          >
            Cancel
          </Button>

          <Button
            onClick={onClickDelete}
            disabled = {categoryToDelete == null? true: false}
            _hover={{ bg: "red.600" }}
            fontSize={{ sm: "14px", md: "16px", lg: "18px" }}
            w={{ sm: "70%", md: "80%", lg: "90%" }}
            minH="30px"
            minW="50px"
            px={4}
            color="white"
            bg="red.500"
            border="1px solid red"
            borderRadius="12px"
            h="100%"
            marginTop="10px"
          >
            Delete
          </Button>
          </Stack>
        </HStack>
      )}
    </Stack>
  )
}

export default DeleteCategory