import React from 'react'
import { Alert } from '@chakra-ui/react'
function AlertMessageComponent(props) {
  return (
    <Alert.Root status="error">
    <Alert.Indicator />
    <Alert.Content>
      <Alert.Title>An Error occured</Alert.Title>
      <Alert.Description>
        {props.errorMessage}
      </Alert.Description>
    </Alert.Content>
  </Alert.Root>
  )
}

export default AlertMessageComponent
