import React from 'react'
import { Portal, ProgressPropsProvider, Select, createListCollection, useFileUploadStyles } from "@chakra-ui/react"
import { useDispatch, useSelector } from 'react-redux'
import { applyFilter, removeFilter, setInitialFilters, setNameToHighlight, setCategoryPath, setKeywordSearchValue, setKeyWordSearchIsLoading, setSelectedFilters, resetAppliedFilters,setSelectedCategory, setFullProductsList, setCurrentPage, setFiltersErrorMessage, setFiltersObject, setFiltersloading, setKeyWordSearchErrorMessage, setProductsList, setSearchList, setSelectedCategoryNotFound, setTotalItems } from '../../state/searchState/searchSlice'
import api from '../../api';

function FilterComponent(props) {
    const filtersLoading = useSelector((state)=>state.search.filtersLoading)
    const selectedCategory = useSelector((state)=>state.search.selectedCategory)
    const applied_filters = useSelector((state)=>state.search.applied_filters)
    const filtersObject = useSelector((state) => state.search.filtersObject);
    const keys_to_aggregate = Object.keys(filtersObject);
    const full_products_list =  useSelector((state) => state.search.full_products_list);
    const initial_filters = useSelector((state) => state.search.initial_filters);
    const dispatch = useDispatch()



    const handleValueChange = async (details) => {
  if (details.value.length === 0) {
    await handleFilterCancel()
  } else {
    await handleFilterSelect(details.value)
  }
}

function resetAll(){
    dispatch(setFiltersObject(null))
    dispatch(setProductsList([]))
    dispatch(setSelectedCategory(null))
    dispatch(setNameToHighlight(""))
    dispatch(setCategoryPath(""))
    dispatch(setFullProductsList([]))
    dispatch(setInitialFilters(null))
    dispatch(setCurrentPage(1))
    dispatch(setKeywordSearchValue(""))
    dispatch(setKeyWordSearchIsLoading(false))
    dispatch(setKeyWordSearchErrorMessage(""))
    dispatch(setSearchList(null))
    dispatch(setFiltersloading(false))
    dispatch(setSelectedCategoryNotFound(false))
    dispatch(setFiltersErrorMessage(""))
    dispatch(setSelectedFilters({}))
    dispatch(setTotalItems(0))
    dispatch(resetAppliedFilters({}))
  }

async function getFiltersandProducts(updatedFilters = null){
  try{
    dispatch(setFiltersloading(true))
    dispatch(setFiltersErrorMessage(""))
    dispatch(setSearchList(null))
    // Use the passed filters or fall back to current state
    const filtersToUse = updatedFilters !== null ? updatedFilters : applied_filters;
   
    
    const response = await api.post("/get_filters_and_products", {
      "category_id": selectedCategory,
      "applied_filters": filtersToUse,
      "keys_to_aggregate": []
// "keys_to_aggregate": Object.keys(filtersToUse).length === 0 ? [] : keys_to_aggregate    
})
    
    if(response.data["detail"] == "fail"){
      throw Error(response.data["message"])
    }
    if( response.status != 200){
      throw Error()
    }
    if(response.data["detail"] ==  "category not processed yet"){
    
      dispatch(setFiltersloading(false))
      dispatch(setSelectedCategoryNotFound(true))
      dispatch(setKeyWordSearchErrorMessage("The category you are looking for is not processed yet."))
      // dispatch(setFiltersErrorMessage("The category you are looking for is not processed yet."))
      return
    }
    dispatch(setFiltersloading(false))
    dispatch(setCurrentPage(1))

    dispatch(setTotalItems(response.data["products"].length))
    dispatch(setProductsList(response.data["products"]))
    dispatch(setFiltersObject(response.data["filters_dict"]))
  }
  catch(e){
    dispatch(setFiltersErrorMessage(String(e)))
    dispatch(setFiltersloading(false))
    resetAll()

  }
}

const handleFilterSelect = async (selectedValues) => {
  // Calculate the new filters
  const newFilters = {
    ...applied_filters,
    [props.nameOfFilter]: selectedValues[0]
  };
  
  dispatch(applyFilter([props.nameOfFilter, selectedValues[0]]))
  console.log("Filter selected:", selectedValues[0])
  
  // Pass the new filters directly
  await getFiltersandProducts(newFilters)
}

const handleFilterCancel = async () => {
  // Calculate filters without this one
  const newFilters = { ...applied_filters };
  delete newFilters[props.nameOfFilter];
   if(Object.keys(newFilters).length === 0){
    console.log("looking for this")
    dispatch(setCurrentPage(1))
    dispatch(setTotalItems(full_products_list.length))
    dispatch(setProductsList(full_products_list))
    dispatch(setFiltersObject(initial_filters))
    console.log("new filters after cancellation")
  console.log(newFilters)
  dispatch(removeFilter(props.nameOfFilter))
  console.log("Filter cleared")
    return
    }
  console.log("new filters after cancellation")
  console.log(newFilters)
  dispatch(removeFilter(props.nameOfFilter))
  console.log("Filter cleared")
  
  // Pass the new filters directly
  await getFiltersandProducts(newFilters)
}

  return (
    <Select.Root
    value={applied_filters[props.nameOfFilter] ? [applied_filters[props.nameOfFilter]] : []}
    onValueChange={handleValueChange}
    disabled = {filtersLoading}
      collection={props.valsCollection}
      size="sm"
      width="320px"
    >
      <Select.HiddenSelect />
      <Select.Label>{props.nameOfFilter}</Select.Label>
      <Select.Control>
        <Select.Trigger >
          <Select.ValueText placeholder={props.nameOfFilter}/>
        </Select.Trigger>
        <Select.IndicatorGroup>
          <Select.ClearTrigger  />
          <Select.Indicator />
        </Select.IndicatorGroup>
      </Select.Control>
      <Portal>
        <Select.Positioner>
          <Select.Content>
            {props.valsCollection.items.map((val) => (
              <Select.Item   item={val} key={val.value}>
                {val.label}
                <Select.ItemIndicator />
              </Select.Item>
            ))}
          </Select.Content>
        </Select.Positioner>
      </Portal>
    </Select.Root>
  )
}

export default FilterComponent
