import { Stack ,Box, Progress, Combobox, ProgressCircle,  HStack, Select, Button, createListCollection, Portal, useFilter, useListCollection} from '@chakra-ui/react'
import React, { useEffect, useMemo, useState} from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { setAddNewCategoryLoading, setAllPossibleCategories, setAllPossibleCategoriesLoading, setCategoryToAdd, setShowCategoryAdd, setShowCategoryUpload } from '../../state/searchState/searchSlice'
import toast from 'react-hot-toast'
import api from '../../api';
function AddNewCategoryPage() {
  const allPossibleCategories = useSelector((state) => state.search.allPossibleCategories)
  const allPossibleCategoriesLoading = useSelector((state) => state.search.allPossibleCategoriesLoading)
  const categoryToAdd = useSelector((state) => state.search.categoryToAdd)
  const addNewCategoryLoading = useSelector((state) => state.search.addNewCategoryLoading)
  const dispatch = useDispatch()

     const [inputValue, setInputValue] = useState('')

  // Create the collection with useMemo
  const categoryCollection = useMemo(() => {
    const itemsList = allPossibleCategories.map(val => ({
      label: val,
      value: val
    }))
    return createListCollection({ items: itemsList })
  }, [allPossibleCategories])



  // Filter items based on input
  const filteredItems = useMemo(() => {
    if (!inputValue) return categoryCollection.items
    
    return categoryCollection.items.filter(item =>
      item.label.toLowerCase().includes(inputValue.toLowerCase())
    )
  }, [categoryCollection.items, inputValue])

  // Create filtered collection
  const filteredCollection = useMemo(() => {
    return createListCollection({ items: filteredItems })
  }, [filteredItems])


   const handleInputChange = (details) => {
    setInputValue(details.inputValue)
  }


const handleValueChange = (details) => {
    dispatch(setCategoryToAdd(details.value[0]))
    console.log(details.value)
  }

  const onClickCancel = () => {
    dispatch(setShowCategoryAdd(false))
    dispatch(setCategoryToAdd(null))
  }


 const onClickAdd = async () => {
   try{
    dispatch(setAddNewCategoryLoading(true))
    var response = await api.post("/process_category",{
        "category_id": categoryToAdd
    })
    if(response.data["detail"] == "fail"){
        throw Error(response.data["message"])
    }
   dispatch(setAddNewCategoryLoading(false))
   toast.success("Category successfully Added.")
   dispatch(setShowCategoryAdd(false))
   dispatch(setCategoryToAdd(null))
   }catch(e){
    dispatch(setAddNewCategoryLoading(false))
    toast.error(String(e))

   }
  }




    useEffect(() => {
    const fetchCategories = async () => {
      try {
        dispatch(setAllPossibleCategoriesLoading(true))
        const response = await api.post("/get_all_possible_categories")
        if (response.data["detail"] === "fail") {
          throw new Error(response.data["message"])
        }
        dispatch(setAllPossibleCategoriesLoading(false))
        dispatch(setAllPossibleCategories(response.data["all_categories"]))
      } catch (e) {
        dispatch(setAllPossibleCategoriesLoading(false))
        dispatch(setShowCategoryAdd(false))
        toast.error(String(e))
      }
    }
    
    fetchCategories()
  }, [dispatch])


  return (
<Stack w="100%" alignItems= "center" h="100%">
    {
allPossibleCategoriesLoading === true ? (
        <Stack w= "100%" gap={50} alignItems= "center">
          <h2 style={{ color: "black", fontWeight: "bolder" }}>Fetching Possible Categories</h2>
          
          <ProgressCircle.Root value={null} size="sm">
                               <ProgressCircle.Circle colorPalette="black">
                                 <ProgressCircle.Track />
                                 <ProgressCircle.Range />
                               </ProgressCircle.Circle>
                             </ProgressCircle.Root>
        </Stack>
      ) : addNewCategoryLoading == true? <Stack w= "100%" gap={50} alignItems= "center">
                <h2 style={{ color: "black", fontWeight: "bolder" }}>Adding Category</h2>
              
      
                <ProgressCircle.Root value={null} size="sm">
                                     <ProgressCircle.Circle colorPalette="black">
                                       <ProgressCircle.Track />
                                       <ProgressCircle.Range />
                                     </ProgressCircle.Circle>
                                   </ProgressCircle.Root>
              </Stack>: (
                      <HStack justifyContent="space-evenly">
                        <Combobox.Root
                          value={categoryToAdd != null ? [categoryToAdd] : []}
                          onValueChange={handleValueChange}
                        onInputValueChange={handleInputChange}
                          disabled={addNewCategoryLoading}
                          collection={filteredCollection}
                          size="sm"
                          width="320px"
                        >
                          <Combobox.Label>Category</Combobox.Label>
                          <Combobox.Control>
                        <Combobox.Input placeholder="Type to search" />
                            <Combobox.Trigger>
                            </Combobox.Trigger>
                            <Combobox.IndicatorGroup>
                              <Combobox.ClearTrigger />
                            </Combobox.IndicatorGroup>
                          </Combobox.Control>
                          <Portal>
                            <Combobox.Positioner>
                              <Combobox.Content>
                                {filteredCollection.items.map((val) => (
                                  <Combobox.Item item={val} key={val.value}>
                                 <Combobox.ItemText>{val.label}</Combobox.ItemText>
                                  </Combobox.Item>
                                ))}
                              </Combobox.Content>
                            </Combobox.Positioner>
                          </Portal>
                        </Combobox.Root>
                        <Box
                            w="20px"
                            >
                        
                            </Box>
                        <Stack w= "150px">
                        <Button
                          onClick={onClickCancel}
                          _hover={{ bg: "gray" }}
                          fontSize={{ sm: "14px", md: "16px", lg: "18px" }}
                          w={{ sm: "70%", md: "80%", lg: "90%" }}
                          minH="30px"
                          minW="50px"
                          px={4}
                          color="white"
                          bg="black"
                          border="1px solid black"
                          borderRadius="12px"
                          h="100%"
                          marginTop="10px"
                        >
                          Cancel
                        </Button>
              
                        <Button
                          onClick={onClickAdd}
                          disabled = {categoryToAdd == null? true: false}
                          _hover={{ bg: "red.600" }}
                          fontSize={{ sm: "14px", md: "16px", lg: "18px" }}
                          w={{ sm: "70%", md: "80%", lg: "90%" }}
                          minH="30px"
                          minW="50px"
                          px={4}
                          color="white"
                          bg="red.500"
                          border="1px solid red"
                          borderRadius="12px"
                          h="100%"
                          marginTop="10px"
                        >
                          Add
                        </Button>
                        </Stack>
                      </HStack>
                    )
    }
</Stack>
  )
}

export default AddNewCategoryPage
